UPDATE article_info
SET deleted=1
WHERE article_id=#{articleId}

UPDATE article_revision
SET deleted=1,is_current=0
WHERE article_id=#{articleId}

UPDATE article_info
SET latest_revision_id=published_revision_id
WHERE article_id=#{articleId}

UPDATE article_revision
SET is_current=1
WHERE revision_id=#{revisionId}

UPDATE article_revision
SET state=5
WHERE revision_id=#{revisionId}

UPDATE article_revision
SET state=4
WHERE revision_id=#{revisionId}

mapper.insert:
INSERT INTO article_info(article_id,user_id,title,summary,content,content_type,category_id,cover_image,is_original,tags,status,deleted,latest_revision_id,published_revision_id,create_time,update_time,publish_time,data_source,required_level) SELECT #{projection.articleId},user_id,#{projection.title},#{projection.summary},#{projection.content},#{projection.contentType},#{projection.categoryId},#{projection.coverImage},#{projection.isOriginal},#{projection.tags},1,0,#{projection.revisionId},#{projection.revisionId},(SELECT created_at
FROM article_revision
WHERE article_id=#{projection.articleId}
ORDER BY version_no
LIMIT 1),NOW(3),NOW(3),data_source,#{projection.requiredLevel}
FROM user_info
WHERE user_id=#{projection.userId}

INSERT INTO article_review_log(article_id,revision_id,actor_id,action,reason,content_hash) SELECT #{articleId},revision_id,#{actorId},#{action},#{reason},content_hash
FROM article_revision
WHERE revision_id=#{revisionId}

mapper.update:
UPDATE article_info
SET published_revision_id=#{revisionId}
WHERE article_id=#{articleId}

UPDATE article_info
SET latest_revision_id=#{revisionId}
WHERE article_id=#{articleId}

mapper.select:
SELECT COALESCE(MAX(version_no),0)+1
FROM article_revision
WHERE article_id=#{articleId}

SELECT category_name
FROM category
WHERE category_id=#{categoryId}

SELECT article_id
FROM article_revision
WHERE revision_id=#{revisionId}

SELECT CAST(r.article_id AS CHAR) AS articleId,CAST(r.revision_id AS CHAR) AS revisionId,r.lock_version AS lockVersion,COALESCE(a.status,0) AS articleStatus,r.state AS revisionState,r.version_no AS version,r.review_reason AS reviewReason,JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.title')) AS title,NULLIF(JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.summary')),'null') AS summary,NULLIF(JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.coverImage')),'null') AS coverImage,r.updated_at AS updateTime
FROM article_revision r
LEFT
JOIN article_info a ON a.article_id=r.article_id
WHERE r.author_id=#{userId} AND r.deleted=0 AND r.is_current=1 AND r.state IN(0,1,3,4) AND (a.article_id IS NULL OR (a.deleted=0 AND a.status<>2))
 AND r.state=#{state}

ORDER BY r.updated_at DESC,r.article_id DESC
LIMIT #{size}
OFFSET #{offset}

SELECT CAST(r.revision_id AS CHAR) AS revisionId,CAST(r.article_id AS CHAR) AS articleId,r.version_no AS version,r.state,JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.title')) AS title,u.nick_name AS authorName,r.submitted_at AS submittedAt,r.review_reason AS reason
FROM article_revision r
LEFT
JOIN article_info a ON a.article_id=r.article_id
LEFT
JOIN user_info u ON u.user_id=r.author_id
WHERE r.deleted=0 AND (a.article_id IS NULL OR a.deleted=0) AND r.state=#{state}
ORDER BY r.submitted_at,r.revision_id
LIMIT #{size}
OFFSET #{offset}
